-- BAN MO HINH DANH CHO SQL SERVER DATABASE DIAGRAM.
-- Chay trong database MOI, TRONG, chi dung de dung so do.
-- Giu 43 bang va cac cot; enum H2 duoc doi thanh varchar(255).
-- Gom 39 FK goc + 16 lien ket logic bo sung thanh FK de hien tren diagram.
-- Cac FK bo sung CHUA ton tai trong schema ung dung; day KHONG phai migration production.
-- 5 bang doc lap: system_configs, foods, injury_area_options,
-- muscle_split_configs, recommended_schedule_configs.
-- Khong noi notifications.ref_id vi dich tham chieu phu thuoc ref_type.

SET XACT_ABORT ON;
BEGIN TRANSACTION;
create table [dbo].[chat_messages] (attachment_size bigint, created_at datetime2(6), id bigint IDENTITY(1,1), user_id bigint, content varchar(2000), attachment_name varchar(255), attachment_type varchar(255), attachment_url varchar(255), sender varchar(255), primary key (id));
create table [dbo].[customer_addresses] (default_address bit not null, id bigint IDENTITY(1,1), user_id bigint, address varchar(1000), phone varchar(255), receiver_name varchar(255), primary key (id));
create table [dbo].[customer_product_states] (wishlisted bit not null, id bigint IDENTITY(1,1), product_id bigint, user_id bigint, viewed_at datetime2(6), primary key (id), unique (user_id, product_id));
create table [dbo].[endurance_tests] (plank_seconds integer, pushup_reps integer, squat_reps integer, id bigint IDENTITY(1,1), tested_at datetime2(6), user_id bigint not null unique, primary key (id));
create table [dbo].[exercises] (calories_burned integer, default_duration_seconds integer, default_reps integer, default_sets integer, endurance_score integer, flexibility_score integer, is_active bit, is_assessment bit, maintenance_score integer, muscle_gain_score integer, rest_seconds integer, stamina_cost integer default 10, uses_weight bit, weight_loss_score integer, id bigint IDENTITY(1,1), contraindicated_injuries varchar(255), description varchar(255), image_url varchar(255), name varchar(255), secondary_muscle_groups varchar(255), video_url varchar(255), assessment_metric_type varchar(255), difficulty varchar(255), muscle_group varchar(255), primary key (id));
create table [dbo].[foods] (calories integer, fat_grams float(53), is_active bit, protein_grams float(53), weight_grams float(53), id bigint IDENTITY(1,1), image_url varchar(255), name varchar(255), suitable_goals varchar(255), ingredients varchar(max), instructions varchar(max), primary key (id));
create table [dbo].[injury_area_options] (id bigint IDENTITY(1,1), code varchar(100) not null, label varchar(100) not null, primary key (id), unique (code), unique (label));
create table [dbo].[invoices] (price float(53), regenerate_count integer, cancelled_at datetime2(6), created_at datetime2(6), expires_at datetime2(6), id bigint IDENTITY(1,1), membership_id bigint, paid_at datetime2(6), user_id bigint, qr_raw_payload varchar(1000), cosmetic_item_code varchar(255), deeplink varchar(255), momo_order_id varchar(255) unique, momo_request_id varchar(255), pay_url varchar(255), qr_code_url varchar(255), result_message varchar(255), transaction_id varchar(255), transfer_code varchar(255) unique, invoice_type varchar(255), membership_type varchar(255), status varchar(255), primary key (id));
create table [dbo].[memberships] (end_date date, is_active bit, price float(53), start_date date, created_at datetime2(6), id bigint IDENTITY(1,1), paid_at datetime2(6), user_id bigint, notes varchar(255), payment_method varchar(255), transaction_id varchar(255), membership_type varchar(255), payment_status varchar(255), primary key (id));
create table [dbo].[muscle_split_configs] (sessions_per_week integer not null, id bigint IDENTITY(1,1), day_groups varchar(1000) not null, goal varchar(255) not null, primary key (id), unique (goal, sessions_per_week));
create table [dbo].[notifications] (is_read bit, created_at datetime2(6), id bigint IDENTITY(1,1), ref_id bigint, scheduled_at datetime2(6), sent_at datetime2(6), user_id bigint, message varchar(255), ref_type varchar(255), title varchar(255), type varchar(255), primary key (id));
create table [dbo].[pet_profiles] (current_streak integer, missed_streak integer, web_count integer, last_calculated_at datetime2(6), user_id bigint not null, equipped_hair varchar(255), equipped_pants varchar(255), equipped_shirt varchar(255), aura_tier varchar(255), stage varchar(255), primary key (user_id));
create table [dbo].[plan_muscle_group_weight] (multiplier float(53), id bigint IDENTITY(1,1), workout_plan_id bigint, muscle_group varchar(255), primary key (id), unique (workout_plan_id, muscle_group));
create table [dbo].[product_attribute_values] (attribute_id bigint, id bigint IDENTITY(1,1), value varchar(255) not null, primary key (id));
create table [dbo].[product_attributes] (id bigint IDENTITY(1,1), name varchar(255) not null unique, primary key (id));
create table [dbo].[product_reviews] (rating integer, created_at datetime2(6), id bigint IDENTITY(1,1), order_id bigint, product_id bigint, user_id bigint, comment varchar(2000), images varchar(20000), primary key (id));
create table [dbo].[product_variants] (active bit, price_override float(53), stock integer not null, id bigint IDENTITY(1,1), product_id bigint, sku varchar(255), primary key (id));
create table [dbo].[progress_tracking] (arm_cm float(53), bmi float(53), body_fat_percentage float(53), chest_cm float(53), height float(53), hip_cm float(53), muscle_mass_kg float(53), recorded_date date, thigh_cm float(53), waist_cm float(53), weight float(53), id bigint IDENTITY(1,1), recorded_at datetime2(6), user_id bigint, notes varchar(255), source varchar(255), primary key (id));
create table [dbo].[recommended_schedule_configs] (sessions_per_week integer not null, id bigint IDENTITY(1,1), recommended_days varchar(30) not null, primary key (id), unique (sessions_per_week));
create table [dbo].[roles] (id bigint IDENTITY(1,1), role_name varchar(255) unique, primary key (id));
create table [dbo].[service_ratings] (is_public bit, rating integer, attachment_size bigint, created_at datetime2(6) not null, id bigint IDENTITY(1,1), replied_at datetime2(6), reply_attachment_size bigint, updated_at datetime2(6), user_id bigint, admin_reply varchar(255), attachment_name varchar(255), attachment_type varchar(255), attachment_url varchar(255), comment varchar(255), reply_attachment_name varchar(255), reply_attachment_type varchar(255), reply_attachment_url varchar(255), service_type varchar(255), title varchar(255), primary key (id));
create table [dbo].[session_exercise_logs] (completion_percent integer, duration_seconds integer, is_completed bit, reps_completed integer, sets_completed integer, weight_used_kg float(53), exercise_id bigint, id bigint IDENTITY(1,1), logged_at datetime2(6), session_id bigint, notes varchar(255), primary key (id));
create table [dbo].[shop_cart_items] (quantity integer, id bigint IDENTITY(1,1), product_id bigint, user_id bigint, variant_id bigint, variant_label varchar(255), primary key (id));
create table [dbo].[shop_inventory_movements] (after_stock integer not null, before_stock integer not null, created_at datetime2(6), id bigint IDENTITY(1,1), order_id bigint, product_id bigint, variant_id bigint, reason varchar(1000), actor varchar(255), primary key (id));
create table [dbo].[shop_order_events] (created_at datetime2(6), id bigint IDENTITY(1,1), order_id bigint, note varchar(1000), actor varchar(255), from_status varchar(255), to_status varchar(255), primary key (id));
create table [dbo].[shop_order_items] (line_total float(53), quantity integer, unit_price float(53), id bigint IDENTITY(1,1), order_id bigint, product_id bigint, variant_id bigint, image_url varchar(255), product_name varchar(255), variant_label varchar(255), primary key (id));
create table [dbo].[shop_orders] (discount float(53), shipping_fee float(53), subtotal float(53), total float(53), voucher_discount float(53), created_at datetime2(6), created_by_staff_id bigint, expires_at datetime2(6), id bigint IDENTITY(1,1), paid_at datetime2(6), user_id bigint, note varchar(1000), qr_raw_payload varchar(1000), shipping_address varchar(1000), payment_url varchar(2000), gateway_reference varchar(255) unique, payment_method varchar(255), phone varchar(255), qr_code_url varchar(255), receiver_name varchar(255), transaction_id varchar(255), transfer_code varchar(255) unique, voucher_code varchar(255), channel varchar(255), status varchar(255), primary key (id));
create table [dbo].[shop_products] (active bit, price float(53) not null, sale_price float(53), stock integer not null, created_at datetime2(6), id bigint IDENTITY(1,1), description varchar(2000), images varchar(20000), brand varchar(255), image_url varchar(255), name varchar(255) not null, required_equipment_code varchar(255), suitable_goals varchar(255), category varchar(255), primary key (id));
create table [dbo].[support_messages] (attachment_size bigint, created_at datetime2(6), id bigint IDENTITY(1,1), session_id bigint, content varchar(2000), attachment_name varchar(255), attachment_type varchar(255), attachment_url varchar(255), sender_role varchar(255), primary key (id));
create table [dbo].[support_sessions] (user_rating integer, accepted_at datetime2(6), admin_id bigint, closed_at datetime2(6), created_at datetime2(6), id bigint IDENTITY(1,1), rated_at datetime2(6), user_id bigint, user_rating_comment varchar(1000), subject varchar(255), status varchar(255), primary key (id));
create table [dbo].[system_configs] (config_value float(53), category varchar(255), config_key varchar(255) not null, description varchar(max), primary key (config_key));
create table [dbo].[user_cosmetic_ownership] (id bigint IDENTITY(1,1), purchased_at datetime2(6), user_id bigint not null, cosmetic_code varchar(255) not null, primary key (id), unique (user_id, cosmetic_code));
create table [dbo].[user_profiles] (age integer, available_days_per_week integer, bmi float(53), body_fat_percentage float(53), date_of_birth date, height float(53), initial_weight float(53), preferred_session_duration integer, training_experience_months integer, weight float(53), id bigint IDENTITY(1,1), user_id bigint unique, preferred_training_days varchar(500), available_equipment varchar(1000), disliked_exercises varchar(1000), injury_areas varchar(1000), daily_activity_level varchar(255), gender varchar(255), medical_conditions varchar(255), training_location varchar(255), fitness_level varchar(255), goal varchar(255), primary key (id));
create table [dbo].[users] (email_verified bit, password_reset_attempts integer, status bit, created_at datetime2(6) not null, id bigint IDENTITY(1,1), password_reset_blocked_until datetime2(6), role_id bigint, email varchar(255) not null unique, full_name varchar(255), password varchar(255), phone varchar(255), verification_token varchar(255), primary key (id));
create table [dbo].[variant_attribute_values] (value_id bigint not null, variant_id bigint not null, primary key (value_id, variant_id));
create table [dbo].[voucher_scope_products] (product_id bigint, voucher_id bigint not null);
create table [dbo].[vouchers] (active bit, max_discount_amount float(53), min_order_amount float(53), usage_limit integer, used_count integer, value float(53), created_at datetime2(6), end_at datetime2(6), id bigint IDENTITY(1,1), start_at datetime2(6), code varchar(255) unique, description varchar(255), scope_category varchar(255), scope_type varchar(255), type varchar(255), primary key (id));
create table [dbo].[weekly_reviews] (rating integer, week_number integer, created_at datetime2(6) not null, id bigint IDENTITY(1,1), user_id bigint, workout_plan_id bigint, comment varchar(255), primary key (id), unique (user_id, workout_plan_id, week_number));
create table [dbo].[work_shifts] (cash_at_start float(53), cash_counted float(53), cash_difference float(53), expected_cash float(53), planned_end time(6), planned_start time(6), pos_bank_revenue float(53), pos_cash_revenue float(53), shift_date date, check_in_at datetime2(6), check_out_at datetime2(6), created_at datetime2(6), id bigint IDENTITY(1,1), user_id bigint, handover_note varchar(2000), status varchar(255), primary key (id));
create table [dbo].[workout_plan_days] (day_of_week integer, id bigint IDENTITY(1,1), workout_plan_id bigint, day_name varchar(255), primary key (id));
create table [dbo].[workout_plan_exercises] (base_weight_kg float(53), current_recommended_weight_kg float(53), current_weight_kg float(53), duration_seconds integer, is_assessment bit, order_index integer, recommended_weight_kg float(53), reps integer, rest_seconds integer, sets integer, weight_updated_week integer, exercise_id bigint, id bigint IDENTITY(1,1), last_low_adjustment_log_id bigint, plan_day_id bigint, notes varchar(255), primary key (id));
create table [dbo].[workout_plans] (current_mana integer, current_week integer, difficulty_adjustment integer, duration_weeks integer, estimated_weeks integer, exercises_adjustment integer, fitness_score integer, is_active bit, is_ai_generated bit, is_completed bit, is_fitness_improvement bit, is_template bit, last_mana_regen_date date, last_training_date date, max_mana integer, reps_adjustment integer, required_max_session_mana_cost integer, sessions_per_week integer, sets_adjustment integer, starting_bmi float(53), starting_weight float(53), target_achieved bit, target_baseline_value float(53), target_current_value float(53), target_goal_value float(53), target_metric_type tinyint check (target_metric_type between 0 and 2), week_start_date date, created_at datetime2(6), id bigint IDENTITY(1,1), original_plan_id bigint, user_id bigint, confirmed_schedule_dows varchar(255), description varchar(255), plan_name varchar(255), weight_adjustment_note varchar(255), body_type varchar(255), fitness_level varchar(255), goal varchar(255), target_level varchar(255), primary key (id));
create table [dbo].[workout_sessions] (checkout_body_fat float(53), checkout_weight float(53), completion_rate integer, duration_minutes integer, is_custom bit, is_last_session_of_week bit, scheduled_time time(6), session_date date, total_calories_burned integer, week_number integer, check_in_time datetime2(6), check_out_time datetime2(6), id bigint IDENTITY(1,1), plan_day_id bigint, user_id bigint, workout_plan_id bigint, custom_session_name varchar(255), notes varchar(255), status varchar(255), primary key (id));
